<script setup lang="ts">
import type { BsJournalWorkspaceCopy, BsJournalWorkspaceChoices, BsJournalWorkspaceFilters, BsJournalWorkspaceView } from '../types/journalWorkspacePresentation'
import type { BsJournalDetailForm } from '../types/journalDetailPresentation'
import type { BsJournalImportForm, BsDocumentExtractionForm } from '../types/journalImportPresentation'
defineProps<{ copy: BsJournalWorkspaceCopy; view: BsJournalWorkspaceView; choices: BsJournalWorkspaceChoices }>()
const filters = defineModel<BsJournalWorkspaceFilters>('filters', { required: true })
const journal = defineModel<BsJournalDetailForm>('journal', { required: true })
const importForm = defineModel<BsJournalImportForm>('importForm', { required: true })
const extraction = defineModel<BsDocumentExtractionForm>('extraction', { required: true })
const emit = defineEmits<{ create: []; openImport: []; clearFilters: []; retry: []; retryTags: []; saveView: []; removeView: []; sort: [key: string]; page: [direction: number]; openJournal: [id: string]; closeJournal: []; retryJournal: []; retryJournalTags: []; assignTag: []; removeTag: [id: string]; upload: [event: Event]; download: [id: string]; deleteAttachment: [id: string]; reverse: []; closeImport: []; importFile: [event: Event]; importTemplate: []; importPaste: []; importValidate: []; importReset: []; importConfirm: []; importPage: [direction: number]; extractionDocument: [event: Event]; extractionProposal: [event: Event]; extractionReject: []; extractionAccept: [] }>()
function field<K extends keyof BsJournalWorkspaceFilters>(key: K, value: BsJournalWorkspaceFilters[K]) { filters.value = { ...filters.value, [key]: value } }
</script>
<template>
  <BsStack gap="md"><BsPageHeader :title="copy.title" :subtitle="copy.subtitle" :context="view.context" :context-label="copy.context"><template #actions><BsButton v-if="view.canImport" :disabled="!view.ready" @click="emit('openImport')">{{ copy.import }}</BsButton><BsButton v-if="view.canCreate" :disabled="!view.ready" variant="primary" @click="emit('create')"><BsIcon name="add" :size="18"/>{{ copy.create }}</BsButton></template></BsPageHeader>
    <BsCard v-if="view.canRead" padding="md"><BsStack gap="md"><BsInline role="group" :aria-label="copy.type" gap="sm" wrap><BsButton v-for="type in choices.quickTypes" :key="type.value" variant="chip" :aria-pressed="filters.type === type.value" :disabled="!view.ready" @click="field('type', type.value)">{{ type.label }}</BsButton></BsInline><BsGrid :columns="4" gap="md">
      <BsFloatingField :label="copy.search"><BsInput :model-value="filters.search" type="search" :placeholder="copy.searchPlaceholder" :disabled="!view.ready" @update:model-value="field('search', String($event ?? ''))"/></BsFloatingField>
      <BsFloatingField v-for="pair in ([['type', 'types'], ['status', 'statuses'], ['source', 'sources']] as const)" :key="pair[0]" :label="copy[pair[0]]"><BsSelect :model-value="filters[pair[0]]" :label="copy[pair[0]]" :disabled="!view.ready" :options="choices[pair[1]]" option-label="label" option-value="value" native @update:model-value="field(pair[0], String($event))"/></BsFloatingField>
      <BsFloatingField :label="copy.from"><BsInput :model-value="filters.from" type="date" :disabled="!view.ready" @update:model-value="field('from', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.to"><BsInput :model-value="filters.to" type="date" :min="filters.from" :disabled="!view.ready" @update:model-value="field('to', String($event ?? ''))"/></BsFloatingField><BsFloatingField :label="copy.account"><BsSelect :model-value="filters.account" :label="copy.account" :disabled="!view.ready" :options="choices.accounts" option-label="label" option-value="value" native @update:model-value="field('account', String($event))"/></BsFloatingField><BsBox v-if="view.canReadTags"><BsFloatingField :label="copy.tag"><BsSelect :model-value="filters.tag" :label="copy.tag" :disabled="!view.ready || view.tagsFailed" :options="choices.tags" option-label="label" option-value="value" native @update:model-value="field('tag', String($event))"/></BsFloatingField><BsText v-if="view.tagsFailed" role="alert" size="sm" tone="muted">{{ copy.tagError }} <BsButton variant="link" @click="emit('retryTags')">{{ copy.retry }}</BsButton></BsText></BsBox>
    </BsGrid><BsInline gap="md" wrap><BsButton :aria-expanded="filters.expanded" aria-controls="journal-more-filters" :disabled="!view.ready" size="sm" @click="field('expanded', !filters.expanded)">{{ copy.moreFilters }}<BsIcon name="arrowDown" :size="16"/></BsButton><BsButton v-if="view.hasFilters" :disabled="!view.ready" size="sm" @click="emit('clearFilters')">{{ copy.clearFilters }}</BsButton><BsText v-if="!view.loading && !view.failed && !view.validation" role="status" size="sm" tone="muted">{{ copy.count }}</BsText></BsInline>
      <BsGrid v-if="filters.expanded" id="journal-more-filters" :columns="3" gap="md"><BsFloatingField :label="copy.category"><BsSelect :model-value="filters.category" :label="copy.category" :options="choices.categories" option-label="label" option-value="value" native @update:model-value="field('category', String($event))"/></BsFloatingField><BsFloatingField v-for="key in (['min', 'max'] as const)" :key="key" :label="copy[key]"><BsInput :model-value="filters[key]" inputmode="decimal" placeholder="0.00" @update:model-value="field(key, String($event ?? ''))"/></BsFloatingField></BsGrid>
      <BsGrid :columns="1" gap="md"><BsFloatingField :label="copy.savedViews"><BsSelect :model-value="filters.savedView" :label="copy.savedViews" :disabled="view.savedPending || view.saving" :options="choices.savedViews" option-label="label" option-value="value" native @update:model-value="field('savedView', String($event))"/></BsFloatingField><BsFloatingField :label="copy.viewName"><BsInput :model-value="filters.savedName" :maxlength="120" :disabled="view.saving" @update:model-value="field('savedName', String($event ?? ''))" @keyup.enter="emit('saveView')"/></BsFloatingField><BsButton :disabled="view.saving || !filters.savedName.trim()" size="sm" @click="emit('saveView')">{{ copy.saveView }}</BsButton><BsButton :disabled="view.saving || !filters.savedView" size="sm" @click="emit('removeView')">{{ copy.removeView }}</BsButton><BsText v-if="view.savedFailed" role="alert" size="sm" tone="danger">{{ copy.savedError }}</BsText></BsGrid>
    </BsStack></BsCard>
    <BsText v-if="!view.canRead" role="status" tone="muted">{{ copy.denied }}</BsText><BsText v-else-if="view.validation" role="alert" tone="danger">{{ view.validation }}</BsText><BsStateSurface v-else-if="view.failed" state="error" :title="copy.failed" :description="copy.retryHint" :action-label="copy.retry" @action="emit('retry')"/><BsSectionSkeleton v-else-if="view.loading" variant="table" :rows="8"/><BsEmptyState v-else-if="view.empty" :title="copy.empty" :description="copy.emptyHint" :action-label="view.canCreate ? copy.create : undefined" @action="emit('create')"/><BsEmptyState v-else-if="view.noMatch" :title="copy.noMatch" :description="copy.noMatchHint" :action-label="copy.noMatchAction" @action="emit('clearFilters')"/>
    <BsCard v-else padding="none" overflow="hidden"><BsInline gap="md" wrap justify="between"><BsTableDensity :model-value="filters.density" :disabled="!view.preferenceReady" :label="copy.density" :compact-label="copy.compact" :comfortable-label="copy.comfortable" @update:model-value="field('density', $event)"/><BsText role="status" size="sm" tone="muted">{{ view.showing }}</BsText></BsInline><BsBox visibility="desktop"><BsDataTable :value="view.rows" data-key="id" :label="copy.title" :density="filters.density" sticky-header max-height="32rem" :scroll-label="copy.scroll" :columns="[{ key: 'reference', header: copy.reference, ariaSort: view.sorts.find(sort => sort.key === 'journal_reference')?.direction }, { key: 'date', field: 'date', header: copy.date, ariaSort: view.sorts.find(sort => sort.key === 'transaction_date')?.direction }, { key: 'description', header: copy.description }, { key: 'source', field: 'source', header: copy.source, ariaSort: view.sorts.find(sort => sort.key === 'source')?.direction }, { key: 'type', field: 'type', header: copy.type, ariaSort: view.sorts.find(sort => sort.key === 'type')?.direction }, { key: 'status', header: copy.status, ariaSort: view.sorts.find(sort => sort.key === 'status')?.direction }, { key: 'debit', field: 'debit', header: copy.debit, align: 'end', ariaSort: view.sorts.find(sort => sort.key === 'debit')?.direction }, { key: 'credit', field: 'credit', header: copy.credit, align: 'end', ariaSort: view.sorts.find(sort => sort.key === 'credit')?.direction }]" @row-click="event => emit('openJournal', event.data.id)"><template #cell-reference="{ row }"><BsText tone="link" emphasis="semibold">{{ row.reference }}</BsText></template><template #cell-description="{ row }"><BsText>{{ row.description }}</BsText><BsInline v-if="row.tags.length" gap="xs" wrap><BsText v-for="tag in row.tags" :key="tag" size="xs">{{ tag }}</BsText></BsInline></template><template #cell-status="{ row }"><BsStatusBadge :status="row.status"/></template><template v-for="pair in ([['reference', 'journal_reference'], ['date', 'transaction_date'], ['source', 'source'], ['type', 'type'], ['status', 'status'], ['debit', 'debit'], ['credit', 'credit']] as const)" :key="pair[0]" #[`header-${pair[0]}`]><BsButton variant="link" @click="emit('sort', pair[1])">{{ copy[pair[0]] }}</BsButton></template></BsDataTable></BsBox>
      <BsBox visibility="mobile"><BsList marker="none"><BsListItem v-for="row in view.rows" :key="row.id"><BsButton block align="start" @click="emit('openJournal', row.id)"><BsInline gap="md" align="start" justify="between"><BsBox><BsText size="xs" tone="link" emphasis="semibold" truncate>{{ row.reference }}</BsText><BsText size="sm" emphasis="semibold" truncate>{{ row.description }}</BsText><BsText size="xs" tone="muted">{{ row.date }} · {{ row.source }} · {{ row.type }}</BsText></BsBox><BsBox><BsText>{{ copy.debit }}: <BsText as="span" dir="ltr">{{ row.debit }}</BsText></BsText><BsText>{{ copy.credit }}: <BsText as="span" dir="ltr">{{ row.credit }}</BsText></BsText><BsStatusBadge :status="row.status"/></BsBox></BsInline><BsInline v-if="row.tags.length" as="span" gap="xs" wrap><BsText v-for="tag in row.tags" :key="tag" as="span" size="xs">{{ tag }}</BsText></BsInline></BsButton></BsListItem></BsList></BsBox><BsInline wrap justify="between"><BsText size="sm" tone="muted">{{ view.showing }}</BsText><BsInline gap="sm"><BsButton :disabled="view.previousDisabled" size="sm" @click="emit('page', -1)">{{ copy.previous }}</BsButton><BsText as="span" size="sm" tone="muted">{{ view.pageLabel }}</BsText><BsButton :disabled="view.nextDisabled" size="sm" @click="emit('page', 1)">{{ copy.next }}</BsButton></BsInline></BsInline>
    </BsCard>
    <BsJournalImportDialog v-model:form="importForm" v-model:extraction="extraction" :copy="view.import.copy" :view="view.import.view" @close="emit('closeImport')" @file="emit('importFile', $event)" @template="emit('importTemplate')" @paste="emit('importPaste')" @validate="emit('importValidate')" @reset="emit('importReset')" @confirm="emit('importConfirm')" @page="emit('importPage', $event)" @document="emit('extractionDocument', $event)" @proposal="emit('extractionProposal', $event)" @reject="emit('extractionReject')" @accept="emit('extractionAccept')"/>
    <BsJournalDetailDialog v-model:form="journal" :copy="view.journal.copy" :view="view.journal.view" @close="emit('closeJournal')" @retry="emit('retryJournal')" @retry-tags="emit('retryJournalTags')" @assign-tag="emit('assignTag')" @remove-tag="emit('removeTag', $event)" @upload="emit('upload', $event)" @download="emit('download', $event)" @delete="emit('deleteAttachment', $event)" @navigate="emit('openJournal', $event)" @reverse="emit('reverse')"/>
  </BsStack>
</template>
